export function findById(id){return DEALS.find(x=>x.id===id)}
export function search(q){const s=String(q||'').toLowerCase();if(!s)return DEALS.slice();return DEALS.filter(x=>JSON.stringify(x).toLowerCase().includes(s))}
export function enabledOnly(){return DEALS.filter(x=>x.enabled!==false)}
export const COUNT=DEALS.length;

